<!-- Security alert status change: every change needs a comment. Open -> Investigating -> Closed (Resolved or False positive). -->
<template><template v-if="alertDialog.open">
<div class="hub-overlay" style="position: fixed; inset: 0; z-index: 70; background: rgba(5,10,8,0.6); display: flex; align-items: center; justify-content: center; padding: 16px">
<div role="dialog" aria-modal="true" :aria-label="alertDialog.title" style="width: 520px; max-width: 100%; max-height: 100%; overflow-y: auto; display: flex; flex-direction: column; gap: 14px; padding: 20px; border-radius: 20px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-2A3832,#2A3832)">
<div style="display: flex; align-items: center; gap: 10px"><h2 style="flex: 1; margin: 0; font-family: 'Space Grotesk', sans-serif; font-size: 20px">{{ alertDialog.title }}</h2><button type="button" aria-label="Close" @click="alertDialog.cancel" style="width: 34px; height: 34px; border-radius: 50%; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">✕</button></div>
<div style="padding: 10px 12px; border-radius: 12px; background: var(--k-121B17,#121B17); display: flex; flex-direction: column; gap: 4px"><span style="font-size: 14px; overflow-wrap: anywhere">{{ alertDialog.alertTitle }}</span><span style="font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Now: <span :style="alertDialog.statusStyle">{{ alertDialog.status }}</span></span></div>
<template v-if="!alertDialog.isHistory">
<template v-if="alertDialog.isClose"><div style="display: flex; flex-direction: column; gap: 6px"><span style="font-size: 13px; color: var(--k-C9D6CF,#C9D6CF)">How is it closed?</span><div style="display: flex; flex-wrap: wrap; gap: 8px"><template v-for="(o, o__i) in alertDialog.outcomes" :key="o__i"><button type="button" @click="o.pick" :aria-pressed="o.on" :style="`height: 36px; padding: 0 16px; border-radius: 18px; cursor: pointer; font-size: 13px; ${o.on ? 'border: 1px solid var(--k-B8F36B,#B8F36B); background: var(--k-2C3D34,#2C3D34); color: var(--k-E8EFEA,#E8EFEA); font-weight: 600' : 'border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-C9D6CF,#C9D6CF)'}`">{{ o.label }}</button></template></div></div></template>
<label style="display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--k-C9D6CF,#C9D6CF)">{{ alertDialog.commentLabel }}<textarea rows="4" :value="alertDialog.comment" @input="alertDialog.onComment" :aria-invalid="alertDialog.hasErr" placeholder="What did you find or decide?" style="padding: 10px 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px; resize: vertical"></textarea></label>
<div style="display: flex; align-items: center; gap: 8px"><EmojiButton :size="36" shape="10px" @pick="alertDialog.addEmoji"/><template v-if="alertDialog.hasErr"><span role="alert" style="font-size: 13px; color: var(--k-FF9B8A,#FF9B8A)">{{ alertDialog.err }}</span></template></div>
</template>
<div v-if="alertDialog.hasHistory" style="display: flex; flex-direction: column; gap: 8px"><strong style="font-size: 13px">Comments so far</strong>
<template v-for="(h, h__i) in alertDialog.history" :key="h__i"><div style="padding: 8px 12px; border-radius: 10px; background: var(--k-121B17,#121B17); display: flex; flex-direction: column; gap: 2px"><span style="font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ h.who }} · {{ h.status }} · {{ h.when }}</span><span style="font-size: 14px; overflow-wrap: anywhere">{{ h.comment }}</span></div></template></div>
<span v-else-if="alertDialog.isHistory" style="font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">No comments yet.</span>
<div style="display: flex; gap: 8px; justify-content: flex-end"><button type="button" @click="alertDialog.cancel" style="height: 40px; padding: 0 18px; border-radius: 20px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">{{ alertDialog.isHistory ? 'Close' : 'Cancel' }}</button><button v-if="!alertDialog.isHistory" type="button" @click="alertDialog.confirm" style="height: 40px; padding: 0 22px; border-radius: 20px; border: 0; background: #B8F36B; color: #0F1714; font-weight: 600; cursor: pointer">{{ alertDialog.confirmLabel }}</button></div>
</div>
</div>
</template></template>

<script>
import { hubBindings } from '~/composables/useHub';
export default { name: 'AlertDialog', computed: { ...hubBindings(['sec']).computed, alertDialog() { return this.sec.alertDialog; } } };
</script>
